class IsProjectCollaboratorOrUnassigned(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        if obj.team is None:
            return request.user.is_staff or obj.created_by == request.user
        return obj.team.members.filter(id=request.user.id).exists()

class ProjectBlueprintDetailView(generics.RetrieveAPIView):
    queryset = ProjectBlueprint.objects.all()
    serializer_class = BlueprintSerializer
    permission_classes = [permissions.IsAuthenticated, IsProjectCollaboratorOrUnassigned]
